// The catalogue of figures: what each one is for, the Skills Map skills it belongs to, its props and
// its examples. One source for three readers:
//
//   /figures/            the gallery renders every example from here
//   docs/figures.md      the reference agents read, generated by `npm run figures:docs`
//   tests/figures.test.ts checks that components, catalogue and docs agree
//
// Plain data with no Astro imports, so Node can load it directly.

export type GroupId = 'screens' | 'flows' | 'numbers' | 'decisions' | 'atlas';

export interface Group {
  id: GroupId;
  code: string;
  name: string;
  /** The question a reader is asking when a figure from this group helps. */
  question: string;
  intro: string;
}

export interface PropDoc {
  name: string;
  type: string;
  required?: boolean;
  note: string;
}

export interface Example {
  /** Shown above the example in the gallery when a figure has more than one. */
  label?: string;
  props: Record<string, unknown>;
}

export interface FigureDoc {
  /** Component name, as written in MDX. */
  name: string;
  /** Catalogue code: group letter and number. */
  code: string;
  group: GroupId;
  /** What it is, in one line. */
  what: string;
  /** When to reach for it: entry kind and section, or the situation. */
  use: string[];
  /** When something else is the better choice. */
  avoid?: string;
  /** Atlas territories it serves most. */
  territories: string[];
  /** Atlas skill ids it helps show. */
  skills: string[];
  /** reveal: plays once in view. ambient: keeps moving, can be paused. interactive: responds to input. */
  motion: ('reveal' | 'ambient' | 'interactive')[];
  props: PropDoc[];
  examples: Example[];
  /** Has no frame (no figure number, title, caption or source). */
  frameless?: boolean;
}

