/** Props every figure accepts. They fill the frame: title above, caption and source below. */
export const FRAME_PROPS: PropDoc[] = [
  { name: 'title', type: 'string', note: 'One line above the figure, saying what it shows.' },
  { name: 'caption', type: 'string', note: 'One or two sentences under it: what to read from it.' },
  {
    name: 'evidence',
    type: "'measured' | 'observed' | 'reported' | 'assumed' | 'illustrative'",
    note: 'How the content is known, when it matters: numbers, third-party facts, guesses, or a kind of knowing that differs from the rest of the entry. Leave it out otherwise. Use `illustrative` for example data: it prints a dashed pink mark so nobody reads it as a finding.',
  },
  { name: 'source', type: 'string', note: 'Where it comes from: tool, dates, sample size, version. Only with `evidence`.' },
  { name: 'replay', type: 'boolean', note: 'Shows a Replay button. On by default only where the reveal shows an order (Sequence, Timeline, Journey, ScreenSteps, Rollout, Funnel, LineChart).' },
];

