// ---- MDX snippets, generated from the example props so docs and gallery cannot drift

const IDENT = /^[A-Za-z_$][\w$]*$/;

function str(s: string): string {
  const q = s.includes("'") && !s.includes('"') ? '"' : "'";
  return q + s.replace(/\\/g, '\\\\').replace(new RegExp(q, 'g'), `\\${q}`).replace(/\n/g, '\\n') + q;
}

function lit(v: unknown, indent: number, width: number): string {
  if (typeof v === 'string') return str(v);
  if (v === null || typeof v !== 'object') return String(v);
  const pad = ' '.repeat(indent + 2);
  if (Array.isArray(v)) {
    const flat = `[${v.map((x) => lit(x, 0, Infinity)).join(', ')}]`;
    if (indent + flat.length <= width) return flat;
    return `[\n${v.map((x) => pad + lit(x, indent + 2, width)).join(',\n')},\n${' '.repeat(indent)}]`;
  }
  const entries = Object.entries(v as Record<string, unknown>).filter(([, x]) => x !== undefined);
  const key = (k: string) => (IDENT.test(k) ? k : str(k));
  const flat = `{ ${entries.map(([k, x]) => `${key(k)}: ${lit(x, 0, Infinity)}`).join(', ')} }`;
  if (indent + flat.length <= width) return flat;
  return `{\n${entries.map(([k, x]) => `${pad}${key(k)}: ${lit(x, indent + 2, width)}`).join(',\n')},\n${' '.repeat(indent)}}`;
}

/** The MDX for a figure with these props, as an author would write it in an entry. */
export function toMdx(name: string, props: Record<string, unknown>, width = 100): string {
  const attrs = Object.entries(props)
    .filter(([, v]) => v !== undefined)
    .map(([k, v]) => {
      if (v === true) return k;
      if (typeof v === 'string' && !/["\n\\{}]/.test(v)) return `${k}="${v}"`;
      return `${k}={${lit(v, 2, width)}}`;
    });
  return `<${name}\n${attrs.map((a) => `  ${a}`).join('\n')}\n/>`;
}
